# ============================================================ OAD-03 clase 1
F = ("Ficha 1 (datos inventados). Potencias de 10: 10¹ = 10; 10² = 100; 10³ = 1.000; 10⁶ = 1.000.000. "
     "Un edificio de ejemplo tiene 3 pisos, 3 departamentos por piso y 3 habitaciones por departamento.")
