   Q("El número 0,001 se escribe como potencia de 10 así", "10⁻³", "10³", "10⁻²", "Tres lugares a la izquierda corresponden al exponente −3."),
   Q("{F} 3 × 10⁻² es lo mismo que", "0,03", "0,3", "300", "Con exponente −2 la coma se corre dos lugares a la izquierda."),
   Q("{F} La bacteria de ejemplo, 0,000002 m, se escribe", "2 × 10⁻⁶ m", "2 × 10⁶ m", "2 × 10⁻⁵ m", "La coma se corre 6 lugares y el exponente es negativo."),
   T2("{F} El grosor 0,0003 m, ¿se escribe 3 × 10⁻⁴ m?", "Sí: la coma se corre 4 lugares a la derecha", "No: sería 3 × 10⁻³", "Entre 0,0003 y 3 hay 4 lugares de diferencia."),
   Q("¿Cuál es mayor, 10⁻² o 10⁻³?", "10⁻², que vale 0,01", "10⁻³, que vale 0,001", "son iguales", "Un centésimo es mayor que un milésimo."),
